-- PromRegion56 v7 | Новые требования: два НЕнулевых наблюдения в разных годах 2021-2025.
-- Отчёт Михаила: дополнительные статьи БФО; ООО «Инженерные Технологии» исключено.
-- Для существующей БД: применить после v6. Проверить на копии!
BEGIN;
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
CREATE TABLE IF NOT EXISTS public.v7_metric_observations (
 enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 period_year integer NOT NULL CHECK(period_year BETWEEN 2021 AND 2025),
 metric_code varchar(80) NOT NULL,
 value_numeric numeric NOT NULL,
 source_url text NOT NULL,
 evidence_status varchar(50) NOT NULL,
 precision_kind varchar(60) NOT NULL,
 note text,
 PRIMARY KEY(enterprise_id,period_year,metric_code),
 CONSTRAINT v7_metric_nonzero CHECK (value_numeric <> 0),
 CONSTRAINT v7_source_http CHECK (source_url LIKE 'https://%' OR source_url LIKE 'http://%')
);
CREATE TABLE IF NOT EXISTS public.v7_metric_definitions (
 metric_code varchar(80) PRIMARY KEY, title text NOT NULL, unit varchar(50) NOT NULL, category varchar(80) NOT NULL
);
CREATE TABLE IF NOT EXISTS public.v7_company_sources (
 enterprise_id integer NOT NULL REFERENCES public.enterprises(id) ON DELETE CASCADE,
 source_no integer NOT NULL CHECK(source_no IN (1,2)),
 source_url text NOT NULL,
 source_role varchar(40) NOT NULL,
 PRIMARY KEY(enterprise_id,source_no)
);
-- Удаляем карточки без подходящих рядов из исходного набора (каскадно очищаются дочерние записи).
DELETE FROM public.enterprises WHERE id=88 AND name ILIKE '%Инженерные Технологии%';
DELETE FROM public.enterprises WHERE id=34 AND name ILIKE '%РОСЭлектрод%';
-- Новые карточки, прошедшие критерий двух отчётных лет.

CREATE OR REPLACE VIEW public.v7_eligible_metric_series AS
 SELECT x.enterprise_id, x.metric_code,COUNT(DISTINCT x.period_year)::integer AS years_available,
        MIN(x.period_year) AS min_year,MAX(x.period_year) AS max_year
 FROM public.v7_metric_observations x
 WHERE x.value_numeric IS NOT NULL AND x.value_numeric <> 0
 GROUP BY x.enterprise_id,x.metric_code
 HAVING COUNT(DISTINCT x.period_year)>=2;
CREATE OR REPLACE VIEW public.v7_public_metric_values AS
 SELECT m.*,d.title,d.unit,d.category,e.city_id,e.name AS enterprise_name,e.inn
 FROM public.v7_metric_observations m
 JOIN public.v7_eligible_metric_series s
   ON s.enterprise_id=m.enterprise_id AND s.metric_code=m.metric_code
 JOIN public.enterprises e ON e.id=m.enterprise_id
 JOIN public.v7_metric_definitions d ON d.metric_code=m.metric_code
 JOIN public.cities c ON c.id=e.city_id
 WHERE c.name IN ('Новотроицк','Орск','Оренбург');
CREATE OR REPLACE VIEW public.v7_public_enterprises AS
 SELECT e.* FROM public.enterprises e
 WHERE e.id IN (SELECT DISTINCT enterprise_id FROM public.v7_eligible_metric_series)
 AND e.id NOT IN (88)
 AND e.city_id IN (SELECT id FROM public.cities WHERE name IN ('Новотроицк','Орск','Оренбург'));
CREATE OR REPLACE VIEW public.v7_staff_latest AS
 SELECT DISTINCT ON (s.enterprise_id) s.enterprise_id,s.report_year,s.headcount,s.source_url,s.headcount_definition
 FROM public.enterprise_staff_annual s
 JOIN public.v7_public_enterprises e ON e.id=s.enterprise_id
 WHERE s.headcount>0
 ORDER BY s.enterprise_id,s.report_year DESC;
-- Audit: enforce source count and valid geography in view.
DO $v7validate$
BEGIN
 IF EXISTS (SELECT 1 FROM public.v7_public_enterprises e LEFT JOIN public.v7_eligible_metric_series s ON s.enterprise_id=e.id WHERE s.enterprise_id IS NULL)
  THEN RAISE EXCEPTION 'Enterprise without eligible metric in v7';END IF;
 IF EXISTS (SELECT 1 FROM public.v7_eligible_metric_series WHERE years_available<2)
  THEN RAISE EXCEPTION 'Metric threshold failed in v7';END IF;
 IF EXISTS (SELECT 1 FROM public.v7_company_sources GROUP BY enterprise_id HAVING COUNT(*)>2)
  THEN RAISE EXCEPTION 'More than two sources';END IF;
END $v7validate$;
COMMIT;
